"""Brute‑force solvers for the Clique and SAT problems.

These functions are only used by the test suite to verify the correctness of
the reduction in ``reduce.py``.  They implement the definitions from
``problems.py`` directly and are deliberately simple – performance is not a
concern because the test harness only generates tiny instances.
"""

from __future__ import annotations

from itertools import combinations, product
from typing import Dict, List


def solve_clique(instance: Dict) -> bool:
    """Return True iff the given Clique instance has a clique of size >= k.

    The instance follows the format defined in ``problems.py``:
    ``{"n": int, "edges": List[List[int]], "k": int}``.
    """
    n: int = instance["n"]
    edges: List[List[int]] = instance["edges"]
    k: int = instance["k"]

    # Edge cases from the problem statement.
    if k <= 0:
        return True
    if k == 1:
        return n >= 1
    if k > n:
        return False

    edge_set = {frozenset(e) for e in edges}

    # Check every subset of vertices of size >= k.
    for size in range(k, n + 1):
        for subset in combinations(range(n), size):
            # Verify that every unordered pair is an edge.
            if all(frozenset((u, v)) in edge_set for u, v in combinations(subset, 2)):
                return True
    return False


def solve_sat(instance: Dict) -> bool:
    """Return True iff the given SAT instance is satisfiable.

    Instance format: ``{"num_vars": m, "clauses": List[List[int]]}`` where a
    literal is a signed integer (+v for true, -v for false).  The empty clause
    (``[]``) is unsatisfiable.
    """
    m: int = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]

    # Edge case: a formula with no clauses is trivially satisfiable.
    if not clauses:
        return True
    # If any clause is empty, the formula is unsatisfiable.
    if any(len(c) == 0 for c in clauses):
        return False

    # Enumerate all possible assignments for variables 1..m.
    for values in product([False, True], repeat=m):
        assignment = {i + 1: val for i, val in enumerate(values)}
        satisfied = True
        for clause in clauses:
            clause_sat = False
            for lit in clause:
                var = abs(lit)
                val = assignment[var]
                if (lit > 0 and val) or (lit < 0 and not val):
                    clause_sat = True
                    break
            if not clause_sat:
                satisfied = False
                break
        if satisfied:
            return True
    return False

EOF"}

